async function copy(text) { try { await navigator.clipboard.writeText(text); toast('Copied to clipboard'); } catch { modal('Copy to clipboard', `<p>Your browser blocked clipboard access. Select and copy the text below.</p><textarea class="field" rows="4" readonly>${esc(text)}</textarea>`); } }
