async function submitBusy(form, fn) { const btn = $('button[type="submit"]', form); if (btn?.disabled) return; const original = btn?.innerHTML; if (btn) { btn.disabled = true; btn.innerHTML = 'One moment…'; } $('.error', form)?.remove(); try { await fn(); } catch (err) { formError(form, err.message); } finally { if (btn?.isConnected) { btn.disabled = false; btn.innerHTML = original; } } }
